// EventDirection is who sends each event type: s2c, c2s or local (daemon to TUI only).
var EventDirection = map[EventType]string{
	EventTypeHello:             "s2c",
	EventTypeMessageCreated:    "s2c",
	EventTypeMessageUpdated:    "s2c",
	EventTypeTaskCreated:       "s2c",
	EventTypeTaskUpdated:       "s2c",
	EventTypeTaskClaimed:       "s2c",
	EventTypePresenceChanged:   "s2c",
	EventTypeRunWake:           "s2c",
	EventTypeError:             "s2c",
	EventTypeSubscribe:         "c2s",
	EventTypeMessagePost:       "c2s",
	EventTypeTaskCreate:        "c2s",
	EventTypeDecisionRule:      "c2s",
	EventTypePresenceHeartbeat: "c2s",
	EventTypeWakeAck:           "c2s",
	EventTypeDaemonStatus:      "local",
}

// DecodeEventData decodes an envelope's data into the type x-variants names for its event type.
func DecodeEventData(t EventType, raw json.RawMessage) (any, error) {
	switch t {
	case EventTypeHello:
		var v Hello
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeMessageCreated:
		var v Message
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeMessageUpdated:
		var v MessageUpdated
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeTaskCreated:
		var v Task
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeTaskUpdated:
		var v Task
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeTaskClaimed:
		var v TaskClaimed
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypePresenceChanged:
		var v PresenceChanged
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeRunWake:
		var v RunWake
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeError:
		var v ErrorBody
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeSubscribe:
		var v Subscribe
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeMessagePost:
		var v MessagePost
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeTaskCreate:
		var v TaskCreate
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeDecisionRule:
		var v DecisionRule
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypePresenceHeartbeat:
		var v PresenceHeartbeat
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeWakeAck:
		var v WakeAck
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	case EventTypeDaemonStatus:
		var v DaemonStatus
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		return &v, nil
	}
	return nil, fmt.Errorf("unknown event type %q", t)
}

